extern "C" __device__
void dx_store_pair_vector(
        const float* first,
        const float* second,
        float* destination,
        __half* factor_sidecar,
        long long sample_base,
        int tile_row,
        int first_tile_col,
        int second_tile_col) {
    const int row_origin = tile_row * 32;
    const int first_col_origin = first_tile_col * 32;
    const int second_col_origin = second_tile_col * 32;
    const long long first_sidecar =
        sample_base + (tile_row * 16 + first_tile_col) * 1024;
    const long long second_sidecar =
        sample_base + (tile_row * 16 + second_tile_col) * 1024;
    #pragma unroll
    for (int load = 0; load < 4; ++load) {
        const int pair = threadIdx.x + load * 128;
        const int element = pair * 2;
        const int row = element / 32;
        const int col = element - row * 32;
        const long long first_destination =
            sample_base + static_cast<long long>(row_origin + row) * 512 +
            first_col_origin + col;
        const long long second_destination =
            sample_base + static_cast<long long>(row_origin + row) * 512 +
            second_col_origin + col;
        const float2 first_value =
            *reinterpret_cast<const float2*>(first + element);
        const float2 second_value =
            *reinterpret_cast<const float2*>(second + element);
        *reinterpret_cast<float2*>(destination + first_destination) =
            first_value;
        *reinterpret_cast<float2*>(destination + second_destination) =
            second_value;
        *reinterpret_cast<__half2*>(factor_sidecar + first_sidecar + element) =
            __floats2half2_rn(first_value.x, first_value.y);
        *reinterpret_cast<__half2*>(factor_sidecar + second_sidecar + element) =
            __floats2half2_rn(second_value.x, second_value.y);
    }
    __syncthreads();
}

